"""Class specs for build_spec() in warship.py. Positions in meters: x forward of amidships, y above
the waterline, z to starboard. Dimensions and layouts follow the reference photos and plans in
docs/Ship Reference Photos.pdf (see the notes there on uncertain photos).

Weapon group names must match TYPES[...] in scripts/data.gd (generated by gen_data.py from the
DATA dicts below)."""
import numpy as np
PI = np.pi

SPECS = {}

def spec(name, **kw):
    SPECS[name] = kw
    return kw


