# game data for every class built here (gen_data.py turns this into scripts/ship_types.gd)
DATA = {}
def mounts(names, gun=None, arcs=None):
    out = []
    for i, (g, x, stow, arc) in enumerate(names):
        m = {'g': g, 'x': x, 'stow': stow, 'arc': arc}
        if gun:
            m['gun'] = gun
        out.append(m)
    return out

