# =====================================================================
# US battleships
# =====================================================================

def bb_secondaries(xs, y, z, gun='us5in38tw'):
    """Twin 5-inch along both sides at the given x positions: weapons and data mounts."""
    w, d = [], []
    i = 1
    for x in xs:
        for s in (1, -1):
            nm = 'Mount5%d' % i if i < 10 else 'Mount6%d' % (i - 9)
            w.append(('dp_twin', nm, x, y, s * z, PI / 2 * s))
            d.append({'g': nm, 'x': x, 'stow': PI / 2 * s, 'arc': 'stbd' if s > 0 else 'port', 'gun': gun})
            i += 1
    return w, d

