IJN_TORP = {'name': 'Type 93', 'speed_kn': 48.0, 'range': 8000.0, 'dud': 0.03, 'flood': 330.0}

def jp_aa(items):
    """Triple 25 mm mounts as decorative turning parts (list of names) plus their weapon entries."""
    w, names = [], []
    for i, it in enumerate(items):
        x, y, z, face = it[:4]
        nm = 'AA%d' % (i + 1)
        w.append(('jp25', nm, x, y, z, face, it[4] if len(it) > 4 else 3))
        names.append(nm)
    return w, names

