# ---- IJN heavy cruisers share a layout: three forward twin turrets (1 low, 2 high, 3 low), two aft (4 high, 5 low),
#      torpedo tubes under the aircraft deck amidships, catapults aft of the funnels ----
def ijn_ca(name, L, B, T, bridge_x, bridge_h, bridge_half, funnels, turret_x, torps_x, cat_x, aa, extra_parts=(), fwd_deck=8.0, mid=6.0, deck_mat='deck', crew=900, disp=13000.0, kn=35.0, aux='jp127', aux_x=(10.0, -4.0), break_x=None):
    aa_w, aa_n = jp_aa(aa)
    t1, t2, t3, t4, t5 = turret_x
    parts = [('block', t2 + 8.0, t2 - 8.0, 6.0, mid, mid + 2.4),
             ('deckhouse', bridge_x + 2.0, torps_x[-1] - 10.0, B / 2 - 2.6, mid, mid + 3.0, 3.0),
             ('tower', bridge_x, mid + 3.0, bridge_h, bridge_half, 5, 0.12), ('rangefinder', bridge_x, mid + 3.0 + bridge_h + 0.9, 2.6, 2.0, 5.0),
             ('tripod', bridge_x - 8.0, mid + 3.0, bridge_h + 6.0, 2.6, 5.0)]
    for fx, fh, rx in funnels:
        parts.append(('funnel', fx, mid + 3.0, fh, rx, rx * 0.7, 1.4))
    parts += [('block', t4 + 8.0, t4 - 6.0, 5.6, mid, mid + 2.4), ('pole', cat_x - 12.0, mid + 3.0, 18.0, 4.0),
              ('catapult', cat_x, mid + 3.0, 5.0, 18.0, 0.3), ('catapult', cat_x, mid + 3.0, -5.0, 18.0, -0.3),
              ('floatplane', cat_x, mid + 4.6, 5.0, 0.3, True, 12.0), ('floatplane', cat_x, mid + 4.6, -5.0, -0.3, True, 12.0), ('crane', cat_x - 10.0, mid + 3.0, 0.0, 11.0, 7.0, 1),
              ('boat', funnels[0][0] - 2.0, mid + 4.2, B / 2 - 1.0, 9.0, 2.2), ('boat', funnels[0][0] - 2.0, mid + 4.2, -(B / 2 - 1.0), 9.0, 2.2),
              ('searchlight', funnels[0][0] + 5.0, mid + 3.0, 5.0), ('searchlight', funnels[0][0] + 5.0, mid + 3.0, -5.0)] + list(extra_parts)
