def ijn_bb(name, L, B, T, turrets, cal, bridge_x, bridge_h, bridge_half, funnels, casemates, secondaries, aa, extra=(), fwd=8.6, mid=6.4, bulge=0.0, crew=1400, disp=35000.0, kn=25.0, taper=0.14, deck_mat='wood', cat_x=None, sec_gun='jp127', armor=1.0, gun='jp356'):
    aa_w, aa_n = jp_aa(aa)
    parts = [('deckhouse', bridge_x + 8.0, funnels[-1][0] - 14.0, B / 2 - 3.0, mid, mid + 3.0, 3.0),
             ('tower', bridge_x, mid + 3.0, bridge_h, bridge_half, 6, taper), ('rangefinder', bridge_x, mid + 3.0 + bridge_h + 0.9, 3.0, 2.4, 7.0)]
    for fx, fh, rx in funnels:
        parts.append(('funnel', fx, mid + 3.0, fh, rx, rx * 0.72, 1.6))
    parts += [('tripod', funnels[-1][0] - 10.0, mid + 3.0, 20.0, 3.0, 6.0), ('boat', funnels[0][0] - 4.0, mid + 4.4, B / 2 - 1.5, 10.0, 2.6), ('boat', funnels[0][0] - 4.0, mid + 4.4, -(B / 2 - 1.5), 10.0, 2.6)]
    if casemates:
        parts.append(('casemates', casemates, mid - 1.4))
    if cat_x is not None:
        parts += [('catapult', cat_x, mid, 5.0, 18.0, 0.3), ('floatplane', cat_x, mid + 1.6, 5.0, 0.3, True, 12.0), ('floatplane', cat_x + 10.0, mid, -4.0, 0.0, True, 12.0), ('crane', cat_x - 8.0, mid, -5.0, 11.0, 7.0, -1)]
    parts += list(extra)
    weapons = []
    dm = []
    for i, (tx, raised, face) in enumerate(turrets):
        y = mid + (2.4 if raised else 0.6)
